`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (loop). Reference: golden/reference (mux__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg t1;
  reg t2;
  reg t3;
  reg t4;
  reg t5;
  reg t6;
  reg t7;
  reg t8;
  reg t9;
  reg t10;
  reg t11;
  reg t12;
  reg t13;
  reg t14;
  reg t15;
  reg t16;
  reg [3:0] sel;
  wire [0:0] m_out; wire [0:0] ref_m_out;
  wire clk = tb_clk;
  mux dut (.t1(t1), .t2(t2), .t3(t3), .t4(t4), .t5(t5), .t6(t6), .t7(t7), .t8(t8), .t9(t9), .t10(t10), .t11(t11), .t12(t12), .t13(t13), .t14(t14), .t15(t15), .t16(t16), .sel(sel), .m_out(m_out), .clk(clk));
  mux__ref ref_i (.t1(t1), .t2(t2), .t3(t3), .t4(t4), .t5(t5), .t6(t6), .t7(t7), .t8(t8), .t9(t9), .t10(t10), .t11(t11), .t12(t12), .t13(t13), .t14(t14), .t15(t15), .t16(t16), .sel(sel), .m_out(ref_m_out), .clk(clk));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_m_out[tb_b] !== 1'bx && ref_m_out[tb_b] !== 1'bz && m_out[tb_b] !== ref_m_out[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: m_out = %h, expected %h", $time, tb_cyc, m_out, ref_m_out);
      end
  end endtask
  task tb_props; begin
  end endtask
  reg [0:0] tbc_p_m_out, tbc_t_m_out;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_m_out = tbc_t_m_out | ((ref_m_out ^ tbc_p_m_out) & ~(ref_m_out ^ ref_m_out)); tbc_p_m_out = ref_m_out;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_m_out) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_m_out[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 1 checked outputs toggled, %0d of 1 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 11; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    t1 = 0; t2 = 0; t3 = 0; t4 = 0; t5 = 0; t6 = 0; t7 = 0; t8 = 0; t9 = 0; t10 = 0; t11 = 0; t12 = 0; t13 = 0; t14 = 0; t15 = 0; t16 = 0; sel = 0;
    tbc_t_m_out = 0; tbc_p_m_out = 0;
    for (tb_cyc = 0; tb_cyc < 200; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      t1 = {tb_rand(0)};
      t2 = {tb_rand(0)};
      t3 = {tb_rand(0)};
      t4 = {tb_rand(0)};
      t5 = {tb_rand(0)};
      t6 = {tb_rand(0)};
      t7 = {tb_rand(0)};
      t8 = {tb_rand(0)};
      t9 = {tb_rand(0)};
      t10 = {tb_rand(0)};
      t11 = {tb_rand(0)};
      t12 = {tb_rand(0)};
      t13 = {tb_rand(0)};
      t14 = {tb_rand(0)};
      t15 = {tb_rand(0)};
      t16 = {tb_rand(0)};
      sel = {tb_rand(0)};
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

// ---- reference copy of the golden module (children come from lib/)
`timescale 1ns / 1ps





















module mux__ref(t1,t2,t3,t4,t5,t6,t7,t8,t9,t10,t11,t12,t13,t14,t15,t16,sel,m_out,clk);
input t1,t2,t3,t4,t5,t6,t7,t8,t9,t10,t11,t12,t13,t14,t15,t16;
input [3:0] sel;
input clk;
output reg m_out;


   
	always@(posedge clk )
	begin
	
	case(sel)
	
    0:m_out=t1;
    1:m_out=t2;
    2:m_out=t3;
    3:m_out=t4;
    4:m_out=t5;
    5:m_out=t6;
    6:m_out=t7;
    7:m_out=t8;
    8:m_out=t9;
    9:m_out=t10;
    10:m_out=t11;
    11:m_out=t12;
    12:m_out=t13;
    13:m_out=t14;
    14:m_out=t15;
    15:m_out=t16;
	
     
     endcase
     
	end






endmodule
